        bool contractETHDecrease = (preContractBalance - postContractBalance) == 3 ether;
        bool attackerETHIncrease = (postAttackerBalance - preAttackerBalance) == 3 ether;
        bool attackerBalanceUnchanged = (postAttackerContractBalance == preAttackerContractBalance);
        bool depositorBalanceUnchanged = (postDepositorContractBalance == preDepositorContractBalance);
        bool vulnerabilityExists = contractETHDecrease && attackerETHIncrease && 
                                  attackerBalanceUnchanged && depositorBalanceUnchanged;

        // Final state verification
        assertEq(
